import argparse
import html
import re
import sys
from pathlib import Path

import markdown

CSS = """
body { max-width: 46rem; margin: 2rem auto; padding: 0 1rem; font-family: system-ui, sans-serif; line-height: 1.6; color: #222; }
h1, h2, h3 { line-height: 1.25; }
pre { background: #f5f5f5; padding: 1rem; overflow-x: auto; border-radius: 6px; }
code { background: #f5f5f5; padding: 0.15em 0.3em; border-radius: 3px; }
pre code { background: none; padding: 0; }
blockquote { margin-left: 0; padding-left: 1rem; border-left: 4px solid #ddd; color: #555; }
table { border-collapse: collapse; }
th, td { border: 1px solid #ccc; padding: 0.4rem 0.8rem; }
img { max-width: 100%; }
"""


def extract_title(md_text, default="Document"):
    match = re.search(r"^#\s+(.+?)\s*#*\s*$", md_text, re.MULTILINE)
    return match.group(1) if match else default


def markdown_to_html_page(md_text, title=None):
    if title is None:
        title = extract_title(md_text)
    body = markdown.markdown(md_text, extensions=["extra", "sane_lists"])
    return (
        "<!DOCTYPE html>\n"
        '<html lang="en">\n<head>\n'
        '<meta charset="utf-8">\n'
        '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
        f"<title>{html.escape(title)}</title>\n"
        f"<style>{CSS}</style>\n"
        "</head>\n<body>\n"
        f"{body}\n"
        "</body>\n</html>\n"
    )


def main(argv=None):
    parser = argparse.ArgumentParser(description="Convert a Markdown file to an HTML page.")
    parser.add_argument("input", type=Path, help="input .md file")
    parser.add_argument("-o", "--output", type=Path, help="output .html file (default: same name as input)")
    parser.add_argument("-t", "--title", help="page title (default: first heading or file name)")
    args = parser.parse_args(argv)

    md_text = args.input.read_text(encoding="utf-8")
    title = args.title or extract_title(md_text, default=args.input.stem)
    output = args.output or args.input.with_suffix(".html")
    output.write_text(markdown_to_html_page(md_text, title), encoding="utf-8")
    print(f"Wrote {output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

